/* Updated Concept Board Component - PureRef Style */
import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Upload, Grid, Search } from 'lucide-react';

const colors = {
  primary: '#ff3d7f',
  secondary: '#121212',
  light: '#ffffff',
  accent: '#00dbdd',
};

const ConceptBoard = () => {
  const [conceptArt, setConceptArt] = useState([]);
  const [scale, setScale] = useState(1);
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [dragging, setDragging] = useState(false);
  const [startDrag, setStartDrag] = useState({ x: 0, y: 0 });
  const [newCategory, setNewCategory] = useState('');
  const [newTags, setNewTags] = useState('');
  const fileInputRef = useRef(null);
  const boardRef = useRef(null);

  useEffect(() => {
    const saved = localStorage.getItem('conceptBoard_data');
    if (saved) setConceptArt(JSON.parse(saved));
  }, []);

  useEffect(() => {
    localStorage.setItem('conceptBoard_data', JSON.stringify(conceptArt));
  }, [conceptArt]);

  const handleUpload = (e) => {
    const files = e.target.files;
    Array.from(files).forEach(file => {
      const reader = new FileReader();
      reader.onload = ev => {
        setConceptArt(prev => [...prev, {
          id: Date.now(),
          name: file.name.split('.')[0],
          src: ev.target.result,
          category: newCategory || 'Uncategorized',
          tags: newTags.split(',').map(t => t.trim()),
          x: 0,
          y: 0,
          scale: 1
        }]);
      };
      reader.readAsDataURL(file);
    });
  };

  const handleMouseDown = (e) => {
    if (e.target === boardRef.current) {
      setDragging(true);
      setStartDrag({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseMove = (e) => {
    if (dragging) {
      setOffset(prev => ({
        x: prev.x + e.clientX - startDrag.x,
        y: prev.y + e.clientY - startDrag.y
      }));
      setStartDrag({ x: e.clientX, y: e.clientY });
    }
  };

  const handleMouseUp = () => setDragging(false);

  const handleWheel = (e) => {
    e.preventDefault();
    const newScale = Math.max(0.2, scale - e.deltaY * 0.001);
    setScale(newScale);
  };

  return (
    <div className="w-screen h-screen overflow-hidden bg-[#121212] text-white">
      <div className="p-4 flex justify-between items-center bg-[#1f1f1f]">
        <div className="flex gap-2 items-center">
          <button
            className="bg-[#00dbdd] text-white px-4 py-2 rounded flex items-center"
            onClick={() => fileInputRef.current.click()}
          >
            <Upload className="mr-2" /> Upload
          </button>
          <input
            ref={fileInputRef}
            type="file"
            className="hidden"
            accept="image/*"
            multiple
            onChange={handleUpload}
          />
          <input
            placeholder="Category"
            value={newCategory}
            onChange={e => setNewCategory(e.target.value)}
            className="bg-[#2a2a2a] px-2 py-1 rounded"
          />
          <input
            placeholder="Tags (comma-separated)"
            value={newTags}
            onChange={e => setNewTags(e.target.value)}
            className="bg-[#2a2a2a] px-2 py-1 rounded"
          />
        </div>
        <div className="flex items-center gap-2">
          <Search className="text-gray-400" />
          <input
            placeholder="Search"
            className="bg-[#2a2a2a] px-2 py-1 rounded"
          />
        </div>
      </div>

      <div
        ref={boardRef}
        className="relative w-full h-full cursor-grab"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
        onWheel={handleWheel}
      >
        <div
          className="absolute"
          style={{
            transform: `translate(${offset.x}px, ${offset.y}px) scale(${scale})`,
            transformOrigin: 'top left'
          }}
        >
          {conceptArt.map(item => (
            <div
              key={item.id}
              className="absolute border border-gray-600 rounded shadow-md"
              style={{ left: item.x, top: item.y }}
            >
              <img src={item.src} alt={item.name} className="w-48 h-auto object-cover" />
              <div className="p-1 bg-[#1c1c1c] text-xs">
                {item.name} <span className="text-gray-400">[{item.category}]</span>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default ConceptBoard;
